-- The canonical tables of the domain, in standard SQL. Generated by tests/export_canon.py
-- from the contracts of the packages; a NULL in the CSV files is \N.

CREATE TABLE orders (
    source_id VARCHAR NOT NULL,
    order_id BIGINT NOT NULL,
    order_number VARCHAR NOT NULL,
    order_date DATE NOT NULL,
    order_time TIMESTAMP WITH TIME ZONE NOT NULL,
    financial_status VARCHAR,
    fulfillment_status VARCHAR,
    is_cancelled BOOLEAN NOT NULL,
    in_sales_reports BOOLEAN NOT NULL,
    channel VARCHAR,
    currency VARCHAR NOT NULL,
    platform VARCHAR NOT NULL,
    shipping_country VARCHAR,
    shipping_region VARCHAR,
    shipping_city VARCHAR,
    billing_country VARCHAR,
    billing_region VARCHAR,
    billing_city VARCHAR,
    customer_id BIGINT,
    customer_order_number BIGINT,
    new_vs_repeat VARCHAR,
    days_since_previous_order BIGINT,
    months_since_first_order BIGINT,
    item_quantity BIGINT NOT NULL,
    discount_code_count BIGINT NOT NULL,
    total DECIMAL(38, 8) NOT NULL,
    subtotal DECIMAL(38, 8) NOT NULL,
    discount_total DECIMAL(38, 8) NOT NULL,
    shipping_total DECIMAL(38, 8) NOT NULL,
    tax_total DECIMAL(38, 8) NOT NULL,
    refunded_total DECIMAL(38, 8) NOT NULL,
    net_total DECIMAL(38, 8) NOT NULL
);

CREATE TABLE customers (
    source_id VARCHAR NOT NULL,
    customer_id BIGINT NOT NULL,
    first_order_date DATE NOT NULL,
    last_order_date DATE NOT NULL,
    number_of_orders BIGINT NOT NULL,
    net_total DECIMAL(38, 8) NOT NULL,
    second_order_within_30_days BOOLEAN,
    second_order_within_60_days BOOLEAN,
    second_order_within_90_days BOOLEAN,
    second_order_within_365_days BOOLEAN
);

CREATE TABLE order_lines (
    source_id VARCHAR NOT NULL,
    line_id BIGINT NOT NULL,
    order_id BIGINT NOT NULL,
    in_sales_reports BOOLEAN NOT NULL,
    product_id BIGINT,
    variant_id BIGINT,
    sku VARCHAR,
    title VARCHAR NOT NULL,
    quantity BIGINT NOT NULL,
    current_quantity BIGINT NOT NULL,
    line_total DECIMAL(38, 8) NOT NULL,
    returned_quantity BIGINT NOT NULL,
    returned_amount DECIMAL(38, 8) NOT NULL
);

CREATE TABLE line_categories (
    source_id VARCHAR NOT NULL,
    line_id BIGINT NOT NULL,
    in_sales_reports BOOLEAN NOT NULL,
    category VARCHAR,
    category_path VARCHAR,
    is_direct BOOLEAN NOT NULL,
    quantity BIGINT NOT NULL,
    line_total DECIMAL(38, 8) NOT NULL,
    returned_quantity BIGINT NOT NULL,
    returned_amount DECIMAL(38, 8) NOT NULL
);

CREATE TABLE line_brands (
    source_id VARCHAR NOT NULL,
    line_id BIGINT NOT NULL,
    in_sales_reports BOOLEAN NOT NULL,
    brand VARCHAR,
    quantity BIGINT NOT NULL,
    line_total DECIMAL(38, 8) NOT NULL,
    returned_quantity BIGINT NOT NULL,
    returned_amount DECIMAL(38, 8) NOT NULL
);

CREATE TABLE order_discount_codes (
    source_id VARCHAR NOT NULL,
    order_id BIGINT NOT NULL,
    discount_code VARCHAR NOT NULL,
    in_sales_reports BOOLEAN NOT NULL,
    customer_id BIGINT,
    total DECIMAL(38, 8) NOT NULL,
    discount_total DECIMAL(38, 8) NOT NULL
);

CREATE TABLE refunds (
    source_id VARCHAR NOT NULL,
    refund_id BIGINT NOT NULL,
    order_id BIGINT NOT NULL,
    in_sales_reports BOOLEAN NOT NULL,
    refund_date DATE NOT NULL,
    refund_time TIMESTAMP WITH TIME ZONE NOT NULL,
    refunded_amount DECIMAL(38, 8) NOT NULL
);

CREATE TABLE sales_events (
    source_id VARCHAR NOT NULL,
    event_id VARCHAR NOT NULL,
    event_type VARCHAR NOT NULL,
    order_id BIGINT NOT NULL,
    event_date DATE NOT NULL,
    event_time TIMESTAMP WITH TIME ZONE NOT NULL,
    amount DECIMAL(38, 8) NOT NULL
);

CREATE TABLE products (
    source_id VARCHAR NOT NULL,
    product_id BIGINT NOT NULL,
    title VARCHAR NOT NULL,
    status VARCHAR,
    last_sold_date DATE
);

CREATE TABLE product_categories (
    source_id VARCHAR NOT NULL,
    product_id BIGINT NOT NULL,
    category VARCHAR NOT NULL,
    category_path VARCHAR NOT NULL,
    is_direct BOOLEAN NOT NULL
);

CREATE TABLE product_brands (
    source_id VARCHAR NOT NULL,
    product_id BIGINT NOT NULL,
    brand VARCHAR NOT NULL
);
